const finalItems = [];
const eventTracker = {};
let targetYear = null;
let targetMonth = null;

function pad(n) { return String(n).padStart(2, '0'); }

// 1. EXTRAER LO QUE SÍ ESTÁ EN EL HTML
for (const item of $input.all()) {
    const html = item.json.data || '';
    const rows = html.split(/<tr[^>]*>/i);

    for (let i = 1; i < rows.length; i++) {
        const row = rows[i];
        if (row.includes('<th') || !row.includes('</td>')) continue;

        const cells = row.split(/<td[^>]*>/i).slice(1).map(c => 
            c.split('</td>')[0].replace(/<[^>]+>|&nbsp;/g, '').trim()
        );

        if (cells.length >= 5) {
            const tipo = cells[4];
            if (tipo === 'Apertura' || tipo === 'Cierre') {
                const fechaEventoRaw = cells[0];
                const [fechaPart, horaPart] = fechaEventoRaw.split(' ');
                if (!fechaPart || !horaPart) continue;

                const [dRaw, mRaw, yRaw] = fechaPart.split('/');
                if (!dRaw || !mRaw || !yRaw) continue;

                const d = pad(dRaw), m = pad(mRaw), y = yRaw;

                if (!targetYear) {
                    targetYear = parseInt(y, 10);
                    targetMonth = parseInt(m, 10);
                }

                const key = `${d}/${m}/${y}_${tipo}`;

                if (!eventTracker[key]) {
                    // Extraer solo la hora de la cuenta y forzar formato con ceros
                    const timeMatch = cells[2].match(/(\d{1,2}:\d{1,2}:\d{1,2}\s*[AP]M)/i);
                    let cuentaTime = timeMatch ? timeMatch[1].toUpperCase() : "12:00:00 AM";

                    const tParts = cuentaTime.match(/(\d+):(\d+):(\d+)\s*([AP]M)/);
                    if (tParts) {
                        cuentaTime = `${pad(tParts[1])}:${pad(tParts[2])}:${pad(tParts[3])} ${tParts[4]}`;
                    }

                    eventTracker[key] = {
                        "Fecha_y_Hora_del_evento": `${d}/${m}/${y} ${horaPart}`,
                        "Evento": tipo,
                        "Horario_Cuenta": `${m}/${d}/${y} ${cuentaTime}`
                    };
                }
            }
        }
    }
}

if (!targetYear) {
    targetYear = 2026;
    targetMonth = 2;
}

// 2. INVENTAR LOS QUE REALMENTE FALTAN
const daysInMonth = new Date(targetYear, targetMonth, 0).getDate();

for (let day = 1; day <= daysInMonth; day++) {
    const dStr = pad(day), mStr = pad(targetMonth), yStr = targetYear;

    // EVALUACIÓN MATEMÁTICA DEL DÍA (0 = Domingo)
    const isSunday = new Date(targetYear, targetMonth - 1, day).getDay() === 0;

    ['Apertura', 'Cierre'].forEach(tipo => {
        const key = `${dStr}/${mStr}/${yStr}_${tipo}`;

        if (eventTracker[key]) {
            // Si el dato ya existe en el HTML (incluso si cae en domingo), se mantiene intacto.
            finalItems.push({ json: eventTracker[key] });
        } else if (!isSunday) {
            // Si el dato falta y NO es domingo, se inventa.
            let hCuenta, mCuenta;
            if (tipo === 'Apertura') {
                const mins = 530 + Math.floor(Math.random() * 21); // 08:50 - 09:10
                hCuenta = Math.floor(mins / 60);
                mCuenta = mins % 60;
            } else {
                hCuenta = 19; // 19:00 - 19:20
                mCuenta = Math.floor(Math.random() * 21);
            }
            const sCuenta = Math.floor(Math.random() * 60);

            const ampm = hCuenta >= 12 ? 'PM' : 'AM';
            const h12 = hCuenta % 12 || 12;

            const cuentaTimeStr = `${pad(h12)}:${pad(mCuenta)}:${pad(sCuenta)} ${ampm}`;
            const horarioCuenta = `${mStr}/${dStr}/${yStr} ${cuentaTimeStr}`;

            let hEvento = hCuenta + 4;
            let dEvento = day, mEvento = targetMonth, yEvento = targetYear;

            if (hEvento >= 24) {
                hEvento -= 24;
                dEvento++;
                if (dEvento > daysInMonth) {
                    dEvento = 1;
                    mEvento++;
                    if (mEvento > 12) { mEvento = 1; yEvento++; }
                }
            }

            const fechaEvento = `${pad(dEvento)}/${pad(mEvento)}/${yEvento} ${pad(hEvento)}:${pad(mCuenta)}:${pad(sCuenta)}`;

            finalItems.push({
                json: {
                    "Fecha_y_Hora_del_evento": fechaEvento,
                    "Evento": tipo,
                    "Horario_Cuenta": horarioCuenta
                }
            });
        }
    });
}

// 3. ORDENAR
finalItems.sort((a, b) => {
    const parseDate = (str) => {
        const [dp, tp] = str.split(' ');
        const [d, m, y] = dp.split('/');
        const [h, min, s] = tp.split(':');
        return new Date(y, m - 1, d, h, min, s).getTime();
    };
    return parseDate(a.json.Fecha_y_Hora_del_evento) - parseDate(b.json.Fecha_y_Hora_del_evento);
});

return finalItems;

const items = [];
const ANCHOR_TEXT = "CENTRO DE ENVIOS";
const ANCHOR_PKT = /PKT\s*\d*\s*[\.\,\s]*/g; 
const TARGET_END = "HORA DEL REPORTE"; // Anclaje de detención

for (const item of $input.all()) {
    const inputData = item.json.data || '';
    let nombre_final = "FALLO_EXTRACCION_FINAL"; 

    // 1. Normalización y Limpieza de Puntuación
    let cleanedText = inputData.toUpperCase();

    cleanedText = cleanedText.replace(/<[^>]+>/g, '');
    cleanedText = cleanedText.replace(/&#(\d+);/g, (match, dec) => String.fromCharCode(dec));
    cleanedText = cleanedText.replace(/[\.\,():]/g, ' '); 
    cleanedText = cleanedText.replace(ANCHOR_PKT, ''); 

    // 2. Buscamos el anclaje "CENTRO DE ENVIOS"
    const anchorIndex = cleanedText.indexOf(ANCHOR_TEXT);

    if (anchorIndex !== -1) {
        let citySegment = cleanedText.substring(anchorIndex + ANCHOR_TEXT.length).trim();

        // 3. Eliminación de Claves Descriptivas (CIUDAD, ESTADO, etc.)
        citySegment = citySegment.replace(/SUCURSAL/g, '');
        citySegment = citySegment.replace(/CIUDAD GENERAL ESCOBEDO/g, '');
        citySegment = citySegment.replace(/GENERAL ESCOBEDO/g, '');
        citySegment = citySegment.replace(/JALISCO/g, ''); // ELIMINAMOS EL ESTADO
        citySegment = citySegment.replace(/NUEVO LEÓN/g, '');
        citySegment = citySegment.replace(/SONORA/g, '');
        citySegment = citySegment.replace(/SINALOA/g, '');
        citySegment = citySegment.replace(/CHIHUAHUA/g, '');

        // 4. Forzar Detención Antes de la Hora del Reporte
        const stopIndex = citySegment.indexOf(TARGET_END);
        if (stopIndex !== -1) {
            citySegment = citySegment.substring(0, stopIndex);
        }

        // 5. Limpieza final de espacios
        citySegment = citySegment.replace(/\s{2,}/g, ' ').trim();

        // 6. Capturamos la ciudad remanente
        const cityMatch = citySegment.match(/^([\w\s]+)/);

        if (cityMatch && cityMatch[1]) {
            nombre_final = cityMatch[1].trim();
        }
    }

    // 7. Devolver Resultado (Ajuste para Lista Blanca)
    const sucursales_validas = ["TIJUANA", "QUERÉTARO", "CULIACÁN", "LOS MOCHIS", "GUADALUPE NUEVO LEÓN", "GUADALAJARA", "HERMOSILLO", "CHIHUAHUA", "MONTERREY", "MÉXICO", "ESCOBEDO"];
    let final_clean_name = "DESCONOCIDA";

    if (nombre_final && nombre_final !== "FALLO_EXTRACCION_FINAL") {
        const candidateUpper = nombre_final.toUpperCase();
        for (const valida of sucursales_validas) {
            if (candidateUpper.includes(valida.toUpperCase()) || valida.toUpperCase().includes(candidateUpper)) {
                final_clean_name = valida;
                break;
            }
        }
    }

    items.push({
        json: {
            nombre_sucursal: final_clean_name
        }
    });
}

return items;

